mapper.select:
SELECT asset_id, project_id, name, asset_type, role, os_name, os_version
FROM asset
WHERE asset_id = #{assetId}

mapper.update:
UPDATE asset
SET name = #{name}, asset_type = #{assetType}, role = #{role, jdbcType=VARCHAR},
    os_name = #{osName, jdbcType=VARCHAR}, os_version = #{osVersion, jdbcType=VARCHAR}
WHERE asset_id = #{assetId}

mapper.select:
SELECT ip_id FROM asset_ip
WHERE asset_id = #{assetId} AND address = #{address} AND phase = #{phase}
LIMIT 1

mapper.update:
UPDATE asset_ip
SET asset_id = #{assetId}, address = #{address}, ip_type = #{ipType}, phase = #{phase},
    ext_whitelisted = #{extWhitelisted}, note = #{note, jdbcType=VARCHAR}
WHERE ip_id = #{ipId}
